+import { inputToRecipient, splitBySeparator } from '@proton/shared/lib/mail/recipient';
+
+describe('splitBySeparator', () => {
+    it('splits commas and semicolons, trims tokens, removes brackets, and omits empty tokens', () => {
+        expect(
+            splitBySeparator(' , plus@debye.proton.black, <visionary@debye.proton.black>; pro@debye.proton.black, ; <>')
+        ).toEqual(['plus@debye.proton.black', 'visionary@debye.proton.black', 'pro@debye.proton.black']);
+    });
+
+    it('returns no tokens for empty or separator-only input', () => {
+        expect(splitBySeparator('')).toEqual([]);
+        expect(splitBySeparator(' , ; <>, ')).toEqual([]);
+    });
+});
+
+describe('inputToRecipient', () => {
+    it('uses a plain email for both name and address', () => {
+        expect(inputToRecipient('  email@domain.test  ')).toEqual({
+            Name: 'email@domain.test',
+            Address: 'email@domain.test',
+        });
+    });
+
+    it('uses the bare email for both name and address when bracketed', () => {
+        expect(inputToRecipient('  <email@domain.test>  ')).toEqual({
+            Name: 'email@domain.test',
+            Address: 'email@domain.test',
+        });
+        expect(inputToRecipient('Display Name <email@domain.test>')).toEqual({
+            Name: 'email@domain.test',
+            Address: 'email@domain.test',
+        });
+    });
+});
